function validate([recipes, ingredients, supplies]) {
  const word = s => typeof s === 'string' && /^[a-z]{1,10}$/.test(s);
  if (!Array.isArray(recipes) || recipes.length < 1 || recipes.length > 100) return 'recipes needs 1 to 100 names.';
  if (!Array.isArray(ingredients) || ingredients.length !== recipes.length) return 'ingredients needs one list per recipe.';
  if (!Array.isArray(supplies) || supplies.length < 1 || supplies.length > 100) return 'supplies needs 1 to 100 names.';
  if (![...recipes, ...supplies].every(word)) return 'Names are 1 to 10 lowercase letters.';
  if (new Set([...recipes, ...supplies]).size !== recipes.length + supplies.length) return 'Recipe and supply names must all be different.';
  for (const list of ingredients) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 100) return 'Each recipe needs 1 to 100 ingredients.';
    if (!list.every(word)) return 'Ingredient names are 1 to 10 lowercase letters.';
    if (new Set(list).size !== list.length) return 'A recipe lists each ingredient once.';
  }
  return null;
}

