function findAllRecipes(recipes, ingredients, supplies) {
  const available = new Set(supplies);
  const missing = new Array(recipes.length).fill(0);
  const needers = new Map();

  for (let i = 0; i < recipes.length; i++) {
    for (const item of ingredients[i]) {
      if (available.has(item)) {
        continue;
      }
      missing[i]++;
      if (!needers.has(item)) {
        needers.set(item, []);
      }
      needers.get(item).push(i);
    }
  }

  const queue = [];
  for (let i = 0; i < recipes.length; i++) {
    if (missing[i] === 0) {
      queue.push(i);
    }
  }

  const made = [];
  for (let head = 0; head < queue.length; head++) {
    const recipe = recipes[queue[head]];
    made.push(recipe);
    for (const next of needers.get(recipe) ?? []) {
      missing[next]--;
      if (missing[next] === 0) {
        queue.push(next);
      }
    }
  }
  return made;
}

