function findAllRecipes(recipes, ingredients, supplies) {
  // Keep sweeping over the recipes, cooking any whose items are all held, until a sweep cooks nothing new.
  const have = new Set(supplies);
  const cooked = [];
  let changed = true;
  while (changed) {
    changed = false;
    recipes.forEach((name, i) => {
      if (!have.has(name) && ingredients[i].every(item => have.has(item))) {
        have.add(name);
        cooked.push(name);
        changed = true;
      }
    });
  }
  return cooked;
}

