function generate(rand, size) {
  const large = size === 'large';
  const pick = (k) => Math.floor(rand() * k);
  const used = new Set();
  const name = () => {
    for (;;) {
      const length = large ? 1 + pick(10) : 1 + pick(3);
      let word = '';
      for (let c = 0; c < length; c++) word += String.fromCharCode(97 + pick(large ? 26 : 6));
      if (!used.has(word)) { used.add(word); return word; }
    }
  };
  const n = large ? 100 : 1 + pick(6);
  const recipes = Array.from({ length: n }, name);
  const supplies = Array.from({ length: large ? 100 : 1 + pick(5) }, name);
  const unknown = Array.from({ length: large ? 20 : pick(3) }, name);
  const brokenChance = large ? 0.08 : 0.3;
  const ingredients = recipes.map((recipe, i) => {
    // Mostly supplies and earlier recipes (cookable chains); sometimes a later recipe or an unknown item.
    const pool = [...supplies, ...recipes.slice(0, i)];
    if (rand() < brokenChance) pool.push(...recipes.slice(i + 1), ...unknown);
    const count = Math.min(pool.length, large ? 1 + pick(40) : 1 + pick(4));
    const chosen = new Set();
    while (chosen.size < count) chosen.add(pool[pick(pool.length)]);
    return [...chosen];
  });
  // Shuffle the recipe order so that cookable recipes are not listed in dependency order.
  const order = recipes.map((_, i) => i);
  for (let i = order.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [order[i], order[j]] = [order[j], order[i]];
  }
  return [order.map(i => recipes[i]), order.map(i => ingredients[i]), supplies];
}
